[Form]
public class GUPPriceTermJournalTable extends FormRun implements GUPIEnableDisableForm
{
    NumberSeqFormHandler numberSeqFormHandler;

    InventDimCtrl_Frm inventDimFormSetup;

}

NumberSeqFormHandler numberSeqFormHandler()
{
    if (!numberSeqFormHandler)
    {
        numberSeqFormHandler = NumberSeqFormHandler::newForm(GUPParameters::numRefPriceTermAgreementId().NumberSequenceId,
                                                             element,
                                                             GUPPriceTermJournalTable_ds,
                                                             fieldNum(GUPPriceTermJournalTable, AgreementId));
    }
    return numberSeqFormHandler;
}

    public void close()
    {
        if (numberSeqFormHandler)
        {
            numberSeqFormHandler.formMethodClose();
        }

        super();
    }

    void enableControls(boolean _enable)
    {
        GUPPriceTermJournalTable_ds.allowEdit(_enable);
        GUPPriceTermJournalTable_ds.allowDelete(_enable);

        GUPPriceTermJournalTrans_ds.allowEdit(_enable);
        GUPPriceTermJournalTrans_ds.allowDelete(_enable);
        GUPPriceTermJournalTrans_ds.allowCreate(_enable);

        ValidateButton.enabled(_enable);
        EnableButton.enabled(_enable);
        EnableButton.visible(_enable);
        DisableButton.enabled(!_enable);
        DisableButton.visible(!_enable);

        GUPAddPriceAttributeGroup.enabled(_enable);
        GUPPriceTermJournalTransCopy.enabled(_enable);
    }

    void updateDesign(InventDimFormDesignUpdate mode)
    {
        InventDimParm   inventDimParm       = InventDimParm::allInventDim();
        InventDimParm   inventDimParmEnable = inventDimParm.data();

        inventDimParmEnable.InventSiteIdFlag = NoYes::No;

        switch (mode)
        {
            case InventDimFormDesignUpdate::Init:
                if (! inventDimFormSetup)
                {
                    inventDimFormSetup  = InventDimCtrl_Frm::construct();
                    InventDimAxFormAdapter adapter = InventDimAxFormAdapter::newFromForm(element);
                    inventDimFormSetup.parmCallingElement(adapter);
                    inventDimFormSetup.init();

                    Set validInventDimDSset = new Set(Types::String);
                    InventDimControlIdCollection inventDimControlIdCollection = InventDimControlIdCollection::construct();
                    
                    validInventDimDSset.add(inventDim_ds.name());
                    inventDimFormSetup.parmValidDataSources(validInventDimDSset);

                    inventDimControlIdCollection.add(inventoryDimensions.id(), true);
                    inventDimFormSetup.parmControlIdCollectionEnumerator(inventDimControlIdCollection.getEnumerator());
                }

                inventDimFormSetup.parmSkipOnHandLookUp(true);

                inventDimFormSetup.parmDimParmEnabled(inventDimParmEnable);
                inventDimFormSetup.parmDimParmVisible(inventDimParm);
                inventDimFormSetup.parmDontShowDisabled(false);

                inventDimFormSetup.formSetControls(true);
                break;
        }
    }

        public boolean validateWrite()
        {
            boolean ret;
        
            ret = super();

            ret = element.numberSeqFormHandler().formMethodDataSourceValidateWrite(ret) && ret;
        
            return ret;
        }

        public void write()
        {
            ttsbegin;

            super();

            element.numberSeqFormHandler().formMethodDataSourceWrite();
            
            ttscommit;
        }

        public void delete()
        {
            ttsbegin;

            element.numberSeqFormHandler().formMethodDataSourceDelete();

            super();

            ttscommit;
        }

        public int active()
        {
            int ret;
        
            ret = super();

            element.enableControls(gupPriceTermJournalTable.Status == GUPDisabledEnabled::Disabled);
            element.enableFields_GUPPriceTermJournalTable();
        
            return ret;
        }

        public void create(boolean _append = false)
        {
            super(_append);

            if (GUPPriceTermJournalTrans.LineNum)
            {
                GUPPriceTermJournalTrans_ds.object(fieldNum(GUPPriceTermJournalTrans, LineNum)).skip(true);
            }
        }

        public void write()
        {
            gupPriceTermJournalTrans.InventDimId = InventDim::findOrCreate(inventDim).inventDimId;
            
            if (gupPriceTermJournalTrans.PricingRule && !gupPriceTermJournalTrans.gupPricingRule().PriceAttributeGroup)
            {
                GUPPricingRule::find(gupPriceTermJournalTrans.PricingRule, true).delete();
                gupPriceTermJournalTrans.PricingRule = 0;
            }

            super();
            
            element.enableFields_GUPPriceTermJournalTable();
            GUPPriceTermJournalTrans_ds.reread();
        }

        public void initValue()
        {
            super();

            if (!inventDim.InventSiteId)
            {
                inventDim.InventSiteId = gupPriceTermJournalTable.InventSiteId;
            }
        }

    public void clicked()
    {
        xMenuFunction menuFunction = this.menufunction();

        xArgs args = new Args(element);
        args.parmEnumType(enumNum(GUPPricingAttributeSourceLevel));
        args.parmEnum(enum2int(GUPPricingAttributeSourceLevel::Line));

        if (!gupPriceTermJournalTrans.PricingRule)
        {
            ttsbegin;

            GUPPricingRule rule;
            rule.insert();

            gupPriceTermJournalTrans.PricingRule = rule.RecId;
            gupPriceTermJournalTrans.update();

            ttscommit;
        }

        args.record(gupPriceTermJournalTrans.gupPricingRule());

        menuFunction.run(args);
    }

    public boolean modified()
    {
        boolean ret;

        ret = super();
        GUPPriceTermTable_ds.executeQuery();

        return ret;
    }
